#include <Arduino.h>

void cetakPesan(unsigned long nomor);

unsigned long terakhir = 0;
unsigned long nomorPesan = 0;

void setup() {
  Serial.begin(115200);
}

void loop() {
  const unsigned long sekarang = millis();
  if (sekarang - terakhir >= 1000UL) {
    terakhir = sekarang;
    cetakPesan(++nomorPesan);
  }
}

void cetakPesan(unsigned long nomor) {
  Serial.print("Halo PlatformIO, pesan ");
  Serial.println(nomor);
}
